testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rodarTransacao } from './solution.mjs';

const bancoInicial = () => ({
  contas: [
    { id: 1, saldo: 100 },
    { id: 2, saldo: 50 },
  ],
});

test('comita: aplica todas as operações e devolve o estado novo', () => {
  const banco = bancoInicial();
  const resultado = rodarTransacao(banco, [
    (rascunho) => { rascunho.contas[0].saldo -= 40; },
    (rascunho) => { rascunho.contas[1].saldo += 40; },
  ]);
  assert.deepEqual(resultado, {
    contas: [
      { id: 1, saldo: 60 },
      { id: 2, saldo: 90 },
    ],
  });
  assert.deepEqual(banco, bancoInicial()); // o original ficou intocado
});

test('desfaz tudo quando uma operação lança erro', () => {
  const banco = bancoInicial();
  assert.throws(
    () => rodarTransacao(banco, [
      (rascunho) => { rascunho.contas[0].saldo = 0; },
      () => { throw new Error('saldo insuficiente'); },
    ]),
    /saldo insuficiente/,
  );
  assert.deepEqual(banco, bancoInicial()); // nem a mudança que tinha dado certo vazou
});

test('lista vazia de operações devolve uma cópia com o mesmo conteúdo', () => {
  const banco = bancoInicial();
  const resultado = rodarTransacao(banco, []);
  assert.deepEqual(resultado, bancoInicial());
  assert.notEqual(resultado, banco); // é uma cópia, não o mesmo objeto
});

test('lança erro quando operacoes não é uma lista', () => {
  assert.throws(() => rodarTransacao(bancoInicial(), 'nada'), /lista/);
});

solutionCode:
// Transação simulada: trabalha numa cópia (rascunho) e só devolve o
// resultado se TODAS as operações funcionarem. Se qualquer uma lançar
// erro, o estado original nem é tocado — o "rollback" acontece sozinho.
export function rodarTransacao(estado, operacoes) {
  if (!Array.isArray(operacoes)) {
    throw new Error('operacoes precisa ser uma lista');
  }
  // cópia bem funda: mudanças no rascunho não alcançam o original
  const rascunho = JSON.parse(JSON.stringify(estado));
  for (const operacao of operacoes) {
    operacao(rascunho); // se lançar erro, a gente nem chega no return
  }
  return rascunho; // commit: devolve a cópia com todas as mudanças
}
